import React from 'react';

const Header = () => {
  return (
    <header className="w-full p-6 flex justify-between items-center bg-[#0D0D0D] border-b border-[#F2F2F2]/10 z-50">
      <div className="font-archivo text-2xl tracking-tighter text-[#F2F2F2]">
        RAW<span className="text-[#00F0FF]">.</span>
      </div>
      <div className="text-[10px] font-inter text-[#F2F2F2]/40 uppercase tracking-[0.3em] hidden md:block">
        Real Conversations — No Filters
      </div>
      <div className="flex space-x-4">
        <div className="w-2 h-2 bg-[#00F0FF] rounded-full animate-pulse"></div>
      </div>
    </header>
  );
};

export default Header;
